#include <algorithm>
#include <vector>

std::vector<std::vector<int>> combinationSum(std::vector<int> candidates, int target) {
    std::sort(candidates.begin(), candidates.end());   // required for the break
    std::vector<std::vector<int>> out;
    std::vector<int> current;

    std::function<void(int, int)> backtrack = [&](int start, int sum) {
        if (sum == target) {
            out.push_back(current);
            return;      // all candidates positive, going deeper cannot help
        }

        for (int i = start; i < (int)candidates.size(); i++) {
            // Sorted, so if this one overshoots, so does everything after it.
            if (sum + candidates[i] > target) break;

            current.push_back(candidates[i]);          // choose
            backtrack(i + 1, sum + candidates[i]);     // explore
            current.pop_back();                        // un-choose
        }
    };

    backtrack(0, 0);
    return out;
}
